#include <iostream>
#include <queue>
#include <algorithm>
using namespace std;

class Solver {
    static constexpr int MAXN = 25;
    static constexpr int MAXE = 400005;
    static constexpr int SRC = 501;
    static constexpr int SNK = 502;
    static constexpr int INF = 1000000007;

    char a[MAXN][MAXN], b[MAXN][MAXN];
    int disZ[MAXN][MAXN];
    int disPair[MAXN][MAXN][MAXN][MAXN];
    queue<pair<int, int>> q;
    int head[505], dep[505], vis[505], pre[505];
    int edgeCnt = 0, ans = 0;
    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    struct Edge { int u, v, fl, c, n; } e[MAXE];

    void addEdge(int u, int v, int cap) {
        e[++edgeCnt] = {u, v, 0, cap, head[u]};
        head[u] = edgeCnt;
        e[++edgeCnt] = {v, u, 0, 0, head[v]};
        head[v] = edgeCnt;
    }

    bool bfsLevel() {
        queue<int> qu;
        for (int i = 0; i <= SNK; i++) vis[i] = dep[i] = 0;
        qu.push(SRC);
        vis[SRC] = 1;
        dep[SRC] = 1;
        while (!qu.empty()) {
            int x = qu.front(); qu.pop();
            for (int i = head[x]; i; i = e[i].n) {
                int y = e[i].v;
                if (!vis[y] && e[i].fl < e[i].c) {
                    pre[y] = i;
                    vis[y] = 1;
                    dep[y] = dep[x] + 1;
                    qu.push(y);
                    if (y == SNK) return true;
                }
            }
        }
        return false;
    }

    int dfs(int x, int now) {
        if (x == SNK || !now) return now;
        int rem = now;
        for (int i = head[x]; i; i = e[i].n) {
            int y = e[i].v;
            if (e[i].c > e[i].fl && dep[y] == dep[x] + 1) {
                int delta = dfs(y, min(rem, e[i].c - e[i].fl));
                if (!delta) dep[y] = 0;
                e[i].fl += delta;
                e[((i - 1) ^ 1) + 1].fl -= delta;
                rem -= delta;
                if (rem == 0) break;
            }
        }
        return now - rem;
    }

public:
    int run() {
        int n, limit;
        cin >> n >> limit;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                disZ[i][j] = 10000;
                cin >> a[i][j];
                if (a[i][j] == 'Z') {
                    q.push({i, j});
                    disZ[i][j] = 0;
                }
                if (a[i][j] <= '9')
                    addEdge(SRC, (i - 1) * n + j, a[i][j] - '0');
            }
        }
        while (!q.empty()) {
            int x = q.front().first, y = q.front().second;
            q.pop();
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                if (nx > 0 && ny > 0 && nx <= n && ny <= n && a[nx][ny] <= '9' && disZ[nx][ny] > disZ[x][y] + 1) {
                    disZ[nx][ny] = disZ[x][y] + 1;
                    q.push({nx, ny});
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (a[i][j] > '9') continue;
                for (int k = 1; k <= n; k++)
                    for (int l = 1; l <= n; l++)
                        disPair[i][j][k][l] = 10000;
                q.push({i, j});
                disPair[i][j][i][j] = 0;
                while (!q.empty()) {
                    int x = q.front().first, y = q.front().second;
                    q.pop();
                    for (int f = 0; f < 4; f++) {
                        int nx = x + dx[f], ny = y + dy[f];
                        if (nx > 0 && ny > 0 && nx <= n && ny <= n && a[nx][ny] <= '9' &&
                            disPair[i][j][nx][ny] > disPair[i][j][x][y] + 1 &&
                            disPair[i][j][x][y] < disZ[x][y]) {
                            disPair[i][j][nx][ny] = disPair[i][j][x][y] + 1;
                            q.push({nx, ny});
                        }
                    }
                }
                for (int k = 1; k <= n; k++)
                    for (int l = 1; l <= n; l++)
                        if (disPair[i][j][k][l] <= min(disZ[k][l], limit))
                            addEdge((i - 1) * n + j, (k - 1) * n + l + 100, 10000);
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                cin >> b[i][j];
                if (b[i][j] <= '9')
                    addEdge((i - 1) * n + j + 100, SNK, b[i][j] - '0');
            }
        }
        while (bfsLevel()) ans += dfs(SRC, INF);
        cout << ans;
        return 0;
    }
};

int main() {
    static Solver solver;
    return solver.run();
}
